  "output_head": "Rails.application.routes.draw do
  get "up" => "rails/health#show", as: :rails_health_check
  root to: redirect("/moderate", status: 302)

  scope "/play/:code", controller: :play do
    get "", action: :show, as: :play
    post "join", action: :join, as: :join_play
    post "answer", action: :answer, as: :answer_play
    post "sync", action: :sync, as: :sync_play
    post "leave", action: :leave, as: :leave_play
  end

  namespace :moderate do
    root "quizzes#index"
    resources :games, only: :show do
      member do
        post :advance
        get :sync
      end
    end
    resources :quizzes do
      resources :games, only: :create
      collection do
        get :import, to: "quiz_imports#new"
        post :import, to: "quiz_imports#create"
      end
      get :export, on: :member
      resource :preview, only: :show
      resources :questions, except: [ :index, :show ] do
        member do
          patch :move_up
          patch :move_down
          patch :set_active
        end
      end
    end
  end
end
class ApplicationController < ActionController::Base
end
class PlayController < ApplicationController
  before_action :load_participant

  def show
    prepare_screen
  end

  def join
    @game.with_lock do
      next if @game.ended?
      @player = find_player
      next if @player

      candidate = @game.players.build(browser_key: @browser_key, name: params.permit(:name)[:name])
      if candidate.save
        @player = candidate
      else
        @error = candidate.errors.full_messages.to_sentence
      end
    end
    respond_to_action
  end

  def answer
    option = Integer(params[:option].to_s, 10, exception: false)
    @game.record_answer(@player, number: params[:number].to_s, option: option)
    respond_to_action
  end

  def sync
    renew_presence
    prepare_screen
    if @version == params[:version]
      head :no_content
    else
      render partial: "screen"
    end
  end

  def leave
    @player&.visits&.where(tab: params[:tab].to_s)&.delete_all
    head :no_content
  end

  private
    def load_participant
      no_store
      @game = Game.find_by!(code: params[:code])
      @browser_key = cookies.signed[cookie_name]
      unless @game.ended? || @browser_key
        # Issue the identity on the join page, not in the join response. If
        # that response gets lost on Wi-Fi, retrying still finds the same row.
        @browser_key = SecureRandom.hex(24)
        cookies.permanent.signed[cookie_name] = { value: @browser_key, path: play_path(@game.code), httponly: true, same_site: :lax }
      end
      @player = find_player if @browser_key
    end

    def find_player
      @game.players.find_by(browser_key: @browser_key)
    end

    def cookie_name
      "quizzy_player_#{@game.code}"
    end

    def renew_presence
      PlayerVisit.renew(@player, params[:tab]) if @player && !@game.ended?
    end

    def prepare_screen
      if @game.ended?
        @version = "ended"
      elsif @player
        @round = @game.current_round
        @pick = @round&.answers&.where(player: @player)&.pick(:option_index)
        @version = [@game.version, @player.id, @pick].join(":")
      else
        # Do not replace a guest's partially typed name on phase changes.
        @version = "guest"
      end
    end

    def respond_to_action
      renew_presence
      prepare_screen
      if request.xhr?
        render partial: "screen", status: @error ? :unprocessable_content : :ok
      elsif @error
        render :show, status: :unprocessable_content
      else
        redirect_to play_path(@game.code), status: :see_other
      end
    end
end
module Moderate
  class BaseController < ApplicationController
    layout "moderate"

    prepend_before_action :require_moderator

    private
      def require_moderator
        no_store
        username = ENV["QUIZZY_MODERATOR_USERNAME"]
        password = ENV["QUIZZY_MODERATOR_PASSWORD"]
        if username.present? && password.present?
          http_basic_authenticate_or_request_with name: username, password: password, realm: "Quizzy moderator"
        else
          request_http_basic_authentication("Quizzy moderator")
        end
      end
  end
end
module Moderate
  class GamesController < BaseController
    layout "application"
    before_action :load_game, except: :create

    def create
      game = Game.create_for!(Quiz.find(params[:quiz_id]))
      redirect_to moderate_game_path(game), status: :see_other
    end

    def show
      prepare_screen
    end

    def advance
      @game.advance!(from: params[:version])
      if request.xhr?
        render_screen
      else
        redirect_to moderate_game_path(@game), status: :see_other
      end
    end

    # Only the projector polls the counters. Neither its QR code nor the
    # question markup needs to go over the wire on a change in headcount.
    def sync
      if params[:version] == @game.version
        render json: { counter: counter }
      else
        render_screen
      end
