// A preview is a snapshot. Only the current index and running score survive
// between questions; neither answers nor score leave this page.
function startPreview(preview) {
  const questions = preview.querySelectorAll("template[data-question]");
  const result = preview.querySelector("template[data-result]");
  const screen = preview.querySelector("[data-screen]");
  let index = 0;
  let score = 0;

  function render(focusHeading = true) {
    const template = questions[index] || result;
    screen.replaceChildren(template.content.cloneNode(true));
    const heading = screen.querySelector("h1");
    if (template === result) heading.textContent = `Score: ${score}/${questions.length}`;
    if (focusHeading) heading.focus();
  }

  function reveal(pick) {
    if (pick.disabled) return;
    const right = pick.dataset.correct === "true";
    if (right) score++;
    const choices = pick.closest(".play-options");
    choices.classList.add("is-locked", "is-revealed");
    pick.classList.add("is-picked");
    for (const choice of choices.children) {
      choice.disabled = true;
      if (choice.dataset.correct === "true") {
        choice.classList.add("is-correct");
        const mark = document.createElement("span");
        mark.className = "play-option__mark";
        mark.textContent = "✓ Correct";
        choice.append(mark);
        choice.removeAttribute("aria-label");
      }
    }
    const status = screen.querySelector("[role=status]");
    status.textContent = right ? "Correct!" : "Wrong!";
    status.classList.add(right ? "play-status--right" : "play-status--wrong");
    status.hidden = false;
    screen.querySelector(".play-actions").hidden = false;
  }

  screen.addEventListener("click", event => {
    const button = event.target.closest("button");
    if (!button) return;
    if (button.matches(".play-option")) {
      reveal(button);
    } else if (button.hasAttribute("data-next")) {
      index++;
      render();
    } else if (button.hasAttribute("data-restart")) {
      index = score = 0;
      render();
    }
  });
  render(false);
}

document.querySelectorAll("[data-preview]").forEach(startPreview);
