  class GamesController < BaseController
    layout "application"
    before_action :load_game, except: :create

    def create
      game = Game.create_for!(Quiz.find(params[:quiz_id]))
      redirect_to moderate_game_path(game), status: :see_other
    end

    def show
      prepare_screen
    end

    def advance
      @game.advance!(from: params[:version])
      respond_to_control
    end

    def winners
      mode = params[:mode]
      return head :bad_request unless %w[top draw reset].include?(mode)
      @game.select_winners!(mode)
      respond_to_control
    end

    # Only the projector polls the counters. Neither its QR code nor the
    # question markup needs to go over the wire on a change in headcount.
    def sync
      if params[:version] != @game.version
        render_screen
      elsif @game.lobby? || @game.open?
        render json: { counter: counter }
      else
        head :no_content
      end
    end

    private
      def respond_to_control
        if request.xhr?
          render_screen
        else
          redirect_to moderate_game_path(@game), status: :see_other
        end
      end

      def load_game
        @game = Game.find(params[:id])
      end

      def prepare_screen
        @leaderboard = @game.leaderboard if @game.ended?
        @round = @game.current_round
        @tallies = @round.answers.group(:option_index).count if @game.closed?
        @counter = counter
      end

      def counter
        if @game.lobby?
          "Players: #{@game.present_players.count}"
        elsif @game.open?
          answered = Answer.where(game_round_id: @game.rounds.where(number: @game.round_number).select(:id)).count
          "Answers: #{answered} / #{@game.present_players.count}"
        end
      end

      def render_screen
        prepare_screen
        render partial: "screen"
      end
  end
